@Singleton
static class AppConfig { String env = "PRODUCTION"; }

static class ClockModule extends AbstractModule {
    @Provides
    @Singleton
    Clock provideClock() {
        return Clock.system(ZoneId.of("Europe/Warsaw"));
    }
}

